def logic_121001(agents, world):
    """Bounded reward evidence adaptation rule #121001."""
    reward = torch.tanh(torch.nan_to_num(agents.last_reward, nan=0.0, posinf=0.0, neginf=0.0))
    evidence = torch.tanh(torch.nan_to_num(agents.last_energy_delta, nan=0.0, posinf=0.0, neginf=0.0))
    current = torch.nan_to_num(agents.strategy_confidence, nan=0.0, posinf=2.0, neginf=0.0)
    delta = 0.0000010 * reward * evidence * (1.0 - torch.clamp(current, 0.0, 2.0) / 2.0)
    agents.strategy_confidence = torch.clamp(current + delta, 0.0, 2.0)


def logic_121002(agents, world):
    """Bounded prediction error adaptation rule #121002."""
    reward = torch.tanh(torch.nan_to_num(agents.last_reward, nan=0.0, posinf=0.0, neginf=0.0))
    evidence = torch.tanh(torch.nan_to_num(agents.betrayal_memory, nan=0.0, posinf=0.0, neginf=0.0))
    current = torch.nan_to_num(agents.survival_score, nan=0.0, posinf=2.0, neginf=0.0)
    prediction_error = torch.tanh(evidence - (torch.clamp(current, 0.0, 2.0) - 1.0))
    delta = 0.0000012 * reward * prediction_error
    agents.survival_score = torch.clamp(current + delta, 0.0, 2.0)


def logic_121003(agents, world):
    """Bounded reinforced memory adaptation rule #121003."""
    reward = torch.tanh(torch.nan_to_num(agents.last_reward, nan=0.0, posinf=0.0, neginf=0.0))
    evidence = torch.tanh(torch.nan_to_num(agents.food_access, nan=0.0, posinf=0.0, neginf=0.0))
    current = torch.nan_to_num(agents.foraging_score, nan=0.0, posinf=2.0, neginf=0.0)
    delta = 0.0000014 * reward * evidence - 0.0000140 * (current - 1.0)
    agents.foraging_score = torch.clamp(current + delta, 0.0, 2.0)


def logic_121004(agents, world):
    """Bounded risk gate adaptation rule #121004."""
    reward = torch.tanh(torch.nan_to_num(agents.last_reward, nan=0.0, posinf=0.0, neginf=0.0))
    evidence = torch.tanh(torch.nan_to_num(agents.last_food, nan=0.0, posinf=0.0, neginf=0.0))
    current = torch.nan_to_num(agents.cooperation_score, nan=0.0, posinf=2.0, neginf=0.0)
    gate = torch.sigmoid(2.0 * evidence)
    delta = 0.0000016 * reward * (gate - torch.clamp(current, 0.0, 2.0) / 2.0)
    agents.cooperation_score = torch.clamp(current + delta, 0.0, 2.0)


def logic_121005(agents, world):
    """Bounded social feedback adaptation rule #121005."""
    reward = torch.tanh(torch.nan_to_num(agents.last_reward, nan=0.0, posinf=0.0, neginf=0.0))
    evidence = torch.tanh(torch.nan_to_num(agents.neighbor_energy_gap, nan=0.0, posinf=0.0, neginf=0.0))
    current = torch.nan_to_num(agents.reciprocity_score, nan=0.0, posinf=2.0, neginf=0.0)
    social_signal = torch.tanh(evidence + torch.tanh(agents.help_received) - torch.tanh(agents.conflict_history))
    delta = 0.0000018 * torch.tanh(reward + social_signal) * (1.0 - torch.clamp(current, 0.0, 2.0) / 2.0)
    agents.reciprocity_score = torch.clamp(current + delta, 0.0, 2.0)


